style.css:
/* Full Screen Stylish Facebook Wallpaper Code */
body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  width: 100vw;
  
  /* Link to your Marin Kitagawa image */
  background-image: url('https://i.pinimg.com/736x/84/78/51/84785195f47adb9cdeffa0297c148683.jpg');
  
  /* Keeps the image fixed in place while you scroll */
  background-attachment: fixed;
  
  /* Centers the character perfectly on the screen */
  background-position: center center;
  
  /* Prevents the image from tiling or repeating */
  background-repeat: no-repeat;
  
  /* Scales the image dynamically to fill the background */
  background-size: cover;
  
  /* Blends a soft matching pastel pink glow behind it if the image takes time to load */
  background-color: #ffc2d1;
}
